# Pure lexical POSIX paths: slash is the only separator.
def path_basename(path: str) -> str:
    i = len(path)
    while i > 0 and path[i - 1] != '/':
        i -= 1
    return path[i:]

def path_dirname(path: str) -> str:
    i = len(path)
    while i > 0 and path[i - 1] != '/':
        i -= 1
    head = path[:i]
    if head != '' and head.strip('/') != '':
        return head.rstrip('/')
    return head

def path_join(left: str, right: str) -> str:
    if right.startswith('/') or left == '':
        return right
    if left.endswith('/'):
        return left + right
    return left + '/' + right

def path_normalize(path: str) -> str:
    if path == '':
        return '.'
    prefix = ''
    if path.startswith('/'):
        prefix = '/'
    if path.startswith('//') and (not path.startswith('///')):
        prefix = '//'
    result = ''
    for part in path.split('/'):
        if part != '' and part != '.':
            if part == '..':
                if result != '' and path_basename(result) != '..':
                    result = path_dirname(result)
                elif prefix == '':
                    result = path_join(result, part)
            else:
                result = path_join(result, part)
    result = prefix + result
    if result == '':
        return '.'
    return result
